public class Complex_tanh_TriageGen1Test {

    private static final double EPSILON = 1e-10;







    @Test
    public void testTanh_ImaginaryOnly() {
        // tanh(iy) = i * tan(y)
        double y = 0.5;
        Complex c = new Complex(0.0, y);
        Complex result = c.tanh();

        assertEquals(0.0, result.getReal(), EPSILON);
        assertEquals(Math.tan(y), result.getImaginary(), EPSILON);
    }






}

