import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Complex_tanh_TriageGen1Test {

    private static final double EPSILON = 1e-10;









    @Test
    public void testTanh_ComplexValue() {
        // Manual calculation or known value check
        // tanh(a + bi) = (sinh(2a) + i sin(2b)) / (cosh(2a) + cos(2b))
        double a = 0.5;
        double b = 0.5;
        Complex c = new Complex(a, b);
        Complex result = c.tanh();

        double real2 = 2.0 * a;
        double imag2 = 2.0 * b;
        double denom = Math.cosh(real2) + Math.cos(imag2);
        double expectedReal = Math.sinh(real2) / denom;
        double expectedImag = Math.sin(imag2) / denom;

        assertEquals(expectedReal, result.getReal(), EPSILON);
        assertEquals(expectedImag, result.getImaginary(), EPSILON);
    }




}

